CREATE TRIGGER world_events_array_order_insert BEFORE INSERT ON world_events BEGIN
      SELECT RAISE(ABORT,'KANATA_DUPLICATE_ENTITY_ID') WHERE EXISTS(SELECT 1 FROM entity_ids WHERE id=NEW.id);
      SELECT RAISE(ABORT,'KANATA_DOMAIN_ARRAY_ORDER_REQUIRED') WHERE (EXISTS(SELECT 1 FROM world_events WHERE world_id=NEW.world_id) AND NOT EXISTS(SELECT 1 FROM event_array_order WHERE world_id=NEW.world_id)) OR (EXISTS(SELECT 1 FROM world_effects WHERE world_id=NEW.world_id) AND NOT EXISTS(SELECT 1 FROM effect_array_order WHERE world_id=NEW.world_id)) OR (EXISTS(SELECT 1 FROM effect_baselines WHERE world_id=NEW.world_id) AND NOT EXISTS(SELECT 1 FROM baseline_array_order WHERE world_id=NEW.world_id));
      INSERT INTO event_array_order(world_id,entity_id,ordinal)
        SELECT NEW.world_id,NEW.id,COALESCE(MAX(ordinal)+1,0) FROM event_array_order WHERE world_id=NEW.world_id;
    END

